export const AIDE_VERSION = "2026-10-09";
export const AIDE_THEMES = {"identite":{"id":"identite","title":"Identifier le site et le régime applicable","nature":"Cadrage","scope":"Toutes les trames","popup":"Renseigner le type de local, le combustible, les puissances et les dates avant de sélectionner une règle.","detail":"Le nom de la trame ICPE ne prouve pas le classement réglementaire. Conserver une fiche de contexte par installation : usage du bâtiment, catégorie ERP si pertinente, type de production, combustible réel, rubrique et régime ICPE, puissance thermique nominale et puissance utile distinctes, date de déclaration, date de mise en service, modifications et arrêté préfectoral. Une puissance commerciale sans définition ni preuve ne permet pas de décider un seuil. Les informations de mission, de contrat et de patrimoine servent au rattachement des constats.","checks":["Identifier sans ambiguïté le local","Vérifier les puissances sur plaques et dossiers","Distinguer installation de combustion et sous-station","Archiver les dates et prescriptions locales"],"evidence":["Plaques signalétiques","Dossier ICPE et arrêté préfectoral","Plan du site","Contrat d’exploitation"],"sources":["nom","1978","trames"],"pending":"","review":"contenu de cadrage vérifié"},"classement":{"id":"classement","title":"Classer la combustion ICPE","nature":"Obligation conditionnelle","scope":"Installations de combustion","popup":"Déterminer la rubrique, le régime et les règles de cumul avant d’utiliser les fiches ICPE.","detail":"Pour les combustibles de la rubrique 2910-A, la nomenclature consultée prévoit DC pour 1 ≤ P < 20 MW et E pour 20 ≤ P < 50 MW. Les catégories de combustibles de 2910-B suivent d’autres seuils et régimes. La rubrique 3110 et les exclusions doivent être examinées séparément. La puissance thermique nominale totale concerne les appareils pouvant fonctionner simultanément selon la définition du texte. Une puissance utile saisie dans METRA ne doit pas remplacer automatiquement cette grandeur. Le régime réel et les dates gouvernent la sélection du texte et des dispositions transitoires.","checks":["Recenser tous les appareils et combustibles","Documenter le cumul et les exclusions","Vérifier le régime dans le dossier administratif"],"evidence":["Nomenclature datée","Tableau de puissances thermiques","Dossier administratif"],"sources":["nom"],"pending":"Le moteur complet de classement 2910-B, 2931, 3110 et les textes d’autorisation doivent être validés pour les sites concernés. Ne pas extrapoler les fiches DC à E ou A.","review":"à compléter"},"implantation":{"id":"implantation","title":"Situation du local et accessibilité","nature":"Obligation conditionnelle","scope":"Chaufferie ou sous-station","popup":"Vérifier le niveau du local, les communications et l’accès de maintenance et de secours.","detail":"Décrire sous-sol, rez-de-chaussée, étage, terrasse ou bâtiment séparé, puis les locaux voisins. Relever les chemins d’accès, les obstacles et les possibilités de remplacement des équipements. Les contraintes de chaufferie et de sous-station sont différentes. Ajouter la hauteur disponible et les distances aux tiers comme mesures documentées. Le dossier de conception et les textes applicables permettent ensuite de qualifier les écarts ; une photo d’une pièce propre ne suffit pas à valider son implantation.","checks":["Localiser les accès sur plan","Mesurer les dégagements utiles","Vérifier que le matériel peut être entretenu","Examiner les tiers et locaux contigus"],"evidence":["Plan coté","Photos des accès","Dossier de conception"],"sources":["1978","dc"],"pending":"Les distances et exemptions de chaque régime doivent être appliquées avec leurs conditions et dates.","review":"à compléter"},"issues":{"id":"issues","title":"Nombre d’issues et dégagements","nature":"Obligation conditionnelle","scope":"Chaufferies relevant de l’arrêté de 1978","popup":"Le nombre d’issues dépend de la situation et du type d’installation. Maintenir les dégagements utilisables.","detail":"L’article 5 prévoit des moyens de retraite dans deux directions avec des exceptions permettant une seule direction selon le fluide, la situation et la puissance. La formule « deux portes pour toute chaufferie » serait incorrecte. Pour les cas en terrasse ou bâtiment séparé, lire les seuils et conditions de l’article. L’analyse doit aussi tenir compte des autres prescriptions effectivement applicables au bâtiment. Distinguer absence d’une issue exigée, accès condamné, accès encombré et document manquant.","checks":["Identifier le nombre de directions réellement utilisables","Tester l’ouverture depuis l’intérieur","Photographier les obstacles","Justifier les exceptions retenues"],"evidence":["Plan d’évacuation","Relevé de situation et puissances","Photos et essai d’ouverture"],"sources":["portes"],"pending":"","review":"contenu de cadrage vérifié"},"porte":{"id":"porte","title":"Portes et résistance au feu","nature":"Obligation conditionnelle","scope":"Accès chaufferie et locaux techniques","popup":"Contrôler ouverture, fermeture et classement au feu en fonction de la communication réelle.","detail":"Pour la chaufferie relevant de l’article 5 de 1978, l’ouverture se fait vers la sortie et reste possible depuis l’intérieur malgré le verrouillage extérieur. L’accès intérieur admet notamment un sas avec deux portes pare-flammes 30 minutes ou une porte coupe-feu une heure avec ferme-porte. Les accès extérieurs ont des conditions liées à la distance aux bâtiments et zones accessibles. En ICPE, vérifier aussi les prescriptions spécifiques et leur cumul. Lire le procès-verbal de l’ensemble posé : vantail, huisserie, joints, quincaillerie, mode de pose et support.","checks":["Comparer l’ensemble posé au PV","Tester la fermeture sans obstacle","Vérifier l’ouverture depuis l’intérieur","Repérer les communications"],"evidence":["PV ou rapport de classement","Photo plaque et huisserie","Plan des communications"],"sources":["portes"],"pending":"Traiter explicitement le cas de distance exactement égale à 10 m et les correspondances entre anciens classements et Euroclasses ; éviter une conversion automatique non justifiée.","review":"à compléter"},"panique":{"id":"panique","title":"Barre anti-panique et déverrouillage","nature":"Prescription à déterminer","scope":"Portes d’évacuation","popup":"Vérifier une sortie facile depuis l’intérieur. Le besoin d’une barre anti-panique doit être justifié.","detail":"Séparer l’obligation de pouvoir évacuer et le choix d’un dispositif de fermeture. Une barre absente ne constitue pas à elle seule une non-conformité universelle des chaufferies. Le public, l’usage de la porte, les règles du bâtiment et la configuration de verrouillage gouvernent le choix. Le ferme-porte répond à une autre fonction. Demander la référence de la quincaillerie et le document de conformité de l’ensemble. Le commentaire terrain peut constater un mécanisme bloqué ou une ouverture nécessitant une clé sans inventer une obligation de produit.","checks":["Tester la manœuvre de sortie","Vérifier le verrouillage intérieur","Identifier les usagers et la destination de la porte"],"evidence":["Notice quincaillerie","Essai d’ouverture","Règlement de sécurité applicable"],"sources":["portes"],"pending":"Normes NF EN 1125 et NF EN 179 : édition et domaine d’application à consulter avant prescription de matériel.","review":"à compléter"},"ventilation":{"id":"ventilation","title":"Ventilation basse et haute","nature":"Obligation et dimensionnement distincts","scope":"Chaufferie, ICPE ou sous-station selon profil","popup":"Contrôler le balayage du local et la section libre réelle. Sélectionner la méthode de calcul selon le profil.","detail":"L’article 11 de 1978 demande une amenée basse et une évacuation haute permanentes. En 2910 déclaration, le point 2.6 demande un balayage efficace même après arrêt ; l’article 26 du régime E traite aussi de la prévention des atmosphères dangereuses. Ces prescriptions ne fournissent pas une formule unique ICPE de section. Pour une sous-station, examiner l’article 28. Relever ouvertures directes ou gaines, dispositifs mécaniques, appareils étanches ou non, air de combustion et pertes de charge. L’aide de calcul technique détaillée figure au chapitre Formules.","checks":["Relever la section libre après grille","Vérifier le parcours jusqu’à l’extérieur","Rechercher obturations et recyclage entre VB et VH","Identifier l’air de combustion"],"evidence":["Photos intérieure et extérieure","Dimensions et taux de passage libre","Note aéraulique","Notice des appareils"],"sources":["vent","sstvent","dc","ev","dtu"],"pending":"Formules DTU à confirmer dans l’édition applicable ; pas de calcul automatique pour gaines, ventilation mécanique ou cas hors domaine de la méthode.","review":"à compléter"},"extincteurs":{"id":"extincteurs","title":"Extincteurs et moyens incendie","nature":"Obligation conditionnelle","scope":"Chaufferie gaz, combustibles liquides/solides, ICPE et lieux de travail","popup":"Choisir le nombre et le type selon les risques et les textes applicables. Vérifier accessibilité et maintenance.","detail":"Sous l’article 20 de 1978, le cas gaz prévoit un appareil poudre de performance minimale 5 A–34 B et la mention « Ne pas utiliser sur flamme gaz ». Pour les combustibles solides ou liquides, le texte prévoit deux extincteurs par brûleur, maximum exigible quatre, avec dépôt de sable de 0,10 m³ et pelle. En 2910 DC, le point 4.2 prévoit au moins un appareil par appareil de combustion, maximum exigible deux, adapté aux risques. Le Code du travail prévoit au moins un appareil à eau pulvérisée de 6 L par 200 m² et un appareil par niveau, avec une dotation adaptée aux risques particuliers. Évaluer les prescriptions cumulées ; le maximum cité ne plafonne pas tous les besoins du site.","checks":["Compter appareils de combustion et extincteurs","Lire agent et performance","Vérifier position et signalisation","Consulter le dernier rapport de maintenance"],"evidence":["Photos et étiquettes","Rapport de vérification","Plan d’implantation"],"sources":["1978","dc","exttravail"],"pending":"","review":"contenu de cadrage vérifié"},"gaine":{"id":"gaine","title":"Gaine pompiers","nature":"Obligation conditionnelle","scope":"Chaufferie en sous-sol relevant de l’article 15","popup":"Identifier la gaine de ventilation incendie et vérifier son débouché accessible aux secours.","detail":"L’article 15 prévoit une section de 16 dm², une plus petite dimension d’au moins 20 cm, un débouché extérieur au sol, et une géométrie terminale spécifique ou demi-raccord DN 300 conforme au texte. Les parois ont une exigence au feu ; l’obturateur est démontable sans outillage et le repérage identifie la gaine. La fiche doit conserver le libellé historique ZAG de METRA pour le rattachement tout en demandant la référence exacte du raccord. Ce dispositif ne remplace pas la ventilation permanente ni le désenfumage.","checks":["Mesurer la gaine et son terminal","Vérifier l’accès et l’obturateur","Lire le repérage","Comparer le raccord au dossier"],"evidence":["Plan de gaine","Photos terminal et signalétique","Dimensions et référence du raccord"],"sources":["gaine"],"pending":"","review":"contenu de cadrage vérifié"},"gazdetect":{"id":"gazdetect","title":"Détection gaz et chaîne de sécurité","nature":"Obligation conditionnelle","scope":"Installations gaz selon régime et surveillance","popup":"Vérifier les capteurs, leurs asservissements et les essais de la chaîne complète.","detail":"En 2910 DC, les points 2.13 et 2.16 encadrent les vannes, capteurs, alarmes et mises en sécurité, selon les conditions d’application. Le seuil de mise en sécurité mentionné est 30 % de LIE. Le seul libellé « puissance > 1 MW » ne suffit pas pour qualifier l’installation. La détection doit être analysée avec le gaz réel, la surveillance, les dates et les zones de fuite. Relever les capteurs et leurs références, demander le plan d’implantation et les essais. Une centrale allumée ne prouve ni l’étalonnage ni la fermeture des vannes.","checks":["Lire les références et dates d’étalonnage","Comparer implantation et risques","Vérifier le rapport d’essai complet","Identifier alarmes et organes asservis"],"evidence":["Plan capteurs","Rapport d’étalonnage","Matrice causes-effets","Compte rendu d’essai"],"sources":["dc"],"pending":"Le nombre et l’implantation finale des capteurs nécessitent l’analyse des risques et le dossier de sécurité ; vérifier les dispositions transitoires.","review":"à compléter"},"incendiedetect":{"id":"incendiedetect","title":"Détection incendie","nature":"Obligation conditionnelle","scope":"Installations de combustion","popup":"Vérifier détection, transmission et preuve des essais. Examiner l’applicabilité au-delà du seul sous-sol.","detail":"La préconisation historique « détection incendie si > 1 MW en sous-sol » doit être revue. Le texte DC consulté comporte des exigences et dispositions transitoires couvrant aussi des installations hors sous-sol. La fenêtre doit demander le régime et la date avant d’afficher une obligation. Relever les zones couvertes, le type de capteur, les reports et les défauts. Utiliser le dossier incendie pour juger la couverture, plutôt qu’un nombre arbitraire de cellules par chaudière.","checks":["Repérer les zones couvertes","Rechercher les zones masquées","Lire le dernier essai et les défauts","Comparer au dossier incendie"],"evidence":["Plan de détection","Rapport de maintenance","Dossier incendie"],"sources":["dc"],"pending":"Validation finale de couverture par la conception incendie et le texte propre au régime E ou A.","review":"à compléter"},"desenfumage":{"id":"desenfumage","title":"Désenfumage","nature":"Obligation conditionnelle","scope":"Locaux selon réglementation incendie","popup":"Distinguer évacuation des fumées d’incendie et ventilation de fonctionnement.","detail":"Identifier les ouvrants, exutoires, commandes manuelles et éventuels asservissements. La conformité concerne le fonctionnement de l’ensemble et la conception, pas uniquement la présence d’un ouvrant. Un nombre de déclencheurs ne donne pas à lui seul la capacité de désenfumage. Vérifier la zone desservie, les possibilités d’accès aux commandes, la note de conception et les rapports de maintenance. Une grille haute de ventilation ne doit pas être déclarée automatiquement exutoire de fumées.","checks":["Identifier le dispositif dédié","Vérifier les commandes et leur accès","Lire les essais et la note de conception"],"evidence":["Plan de désenfumage","Note de calcul","Rapport de maintenance"],"sources":["dc","entretien"],"pending":"Dimensionnement et référentiels spécifiques ERP, habitation, ICPE E/A à compléter pour chaque bâtiment.","review":"à compléter"},"alarmes":{"id":"alarmes","title":"Alarmes sonores et visuelles","nature":"Prescription à déterminer","scope":"Détection, local et public concernés","popup":"Vérifier que les alarmes et reports permettent une réaction adaptée dans les zones concernées.","detail":"Identifier l’événement signalé : gaz, incendie, défaut technique ou arrêt d’équipement. Documenter les destinataires, les zones de perception et les conditions d’occupation. La règle « une sirène et un gyrophare par accès » ne doit pas être présentée comme universelle sans texte. Un équipement présent et lumineux peut être en test ou en défaut. Demander un essai tracé, la matrice causes-effets et la stratégie d’intervention de l’exploitant.","checks":["Identifier événements et destinataires","Vérifier perception et reports","Consulter la matrice causes-effets"],"evidence":["Schéma fonctionnel","Rapport d’essai","Consignes d’alarme"],"sources":["entretien"],"pending":"Obligations de signalisation acoustique/visuelle propres à chaque réglementation et public à déterminer.","review":"à compléter"},"parois":{"id":"parois","title":"Parois et compartimentage","nature":"Obligation conditionnelle","scope":"Chaufferies et locaux techniques","popup":"Vérifier le classement des parois et des traversées avec les justificatifs de l’ensemble construit.","detail":"Décrire murs, plancher haut, plancher bas, toiture, portes et traversées. Une finition ou un flocage visible ne permet pas de conclure à une résistance au feu. Rechercher les systèmes testés, épaisseurs, supports et détails de mise en œuvre. La réaction au feu des matériaux et la résistance au feu d’un élément sont deux propriétés distinctes. La prescription de flocage deux heures n’est pas une réponse automatique à chaque défaut : identifier d’abord l’exigence applicable et la solution compatible avec le support.","checks":["Inventorier parois et traversées","Lire les justificatifs","Repérer ouvertures et dégradations","Comparer au dossier de construction"],"evidence":["PV systèmes","Plans coupe-feu","Photos traversées"],"sources":["1978","dc"],"pending":"La sélection des exigences au feu reste conditionnée par l’implantation, le régime et les dates.","review":"à compléter"},"sable":{"id":"sable","title":"Sable et pelle","nature":"Obligation conditionnelle","scope":"Chaufferies à combustibles solides ou liquides relevant de 1978","popup":"Vérifier le dépôt de sable et la pelle si le texte applicable les exige.","detail":"L’aide renvoie à la fiche Extincteurs pour la quantité prescrite par l’article 20. Relever la capacité utile, l’accessibilité et la présence de la pelle ; ne pas assimiler la capacité nominale d’un bac presque vide à une quantité disponible. Ne pas exiger automatiquement ce dispositif dans une sous-station sans combustion ou un local gaz. Il faut aussi examiner les prescriptions incendie propres au site.","checks":["Identifier combustible et domaine","Vérifier quantité disponible","Vérifier accès et pelle"],"evidence":["Photo bac et pelle","Mesure du volume utile"],"sources":["1978"],"pending":"","review":"contenu de cadrage vérifié"},"sprinkler":{"id":"sprinkler","title":"Extinction automatique biomasse","nature":"Prescription à déterminer","scope":"Stockage et alimentation de biomasse","popup":"Vérifier le système prévu contre les incendies et retours de feu dans la configuration réelle.","detail":"Le libellé « Sprinkler (bois) » peut couvrir plusieurs dispositifs : extinction du silo, arrosage, protection de convoyage ou sécurité contre un retour de combustion. Les exigences dépendent du stockage, des équipements et du dossier de risques. Le simple combustible bois ne permet pas de conclure à l’obligation de sprinklage de tout le local. Documenter la fonction, l’alimentation, les essais, le déclenchement et les interfaces avec la chaudière.","checks":["Définir la fonction du dispositif","Identifier les zones couvertes","Vérifier la notice et les essais"],"evidence":["Dossier constructeur biomasse","Étude incendie","Rapport maintenance"],"sources":[],"pending":"Rubriques de stockage, prescriptions préfectorales et notices de chaque équipement à collecter avant conclusion réglementaire.","review":"à compléter"},"affichages":{"id":"affichages","title":"Consignes et plans","nature":"Obligation et aide d’exploitation","scope":"Toutes les installations","popup":"Afficher des consignes utiles et conserver les plans à jour correspondant à l’installation.","detail":"Vérifier les coordonnées d’alerte, le repérage des coupures, les instructions d’urgence et les plans réellement utilisables. Un document présent mais relatif à un autre local est insuffisant. Le schéma hydraulique facilite l’exploitation ; sa qualification comme obligation réglementaire doit être rattachée à un texte ou contrat précis. Pour chaque document, relever version, date, auteur, périmètre et cohérence avec les équipements observés.","checks":["Lire les consignes et contacts","Comparer le plan au terrain","Identifier les coupures","Vérifier la lisibilité"],"evidence":["Copies datées","Photos affichages","Historique de mise à jour"],"sources":["entretien","dc"],"pending":"Ne pas qualifier tous les schémas comme affichages réglementaires obligatoires sans fondement propre.","review":"à compléter"},"evacuation":{"id":"evacuation","title":"Eaux usées, siphon et relevage","nature":"Obligation conditionnelle","scope":"Chaufferie et sous-station","popup":"Identifier les évacuations, leur état et le devenir des eaux, condensats et produits polluants.","detail":"Relever siphon de sol, fosse, pompe, refoulement et risques d’inondation. Les solutions demandées varient avec le niveau du local et le combustible. Le texte de 1978 prévoit notamment des dispositions particulières pour les chaufferies en sous-sol ou en terrasse. Vérifier séparément les prescriptions du service d’assainissement pour les rejets. Les déchets et produits chimiques ne se confondent pas avec les eaux de lavage. La présence d’un caillebotis est un constat d’équipement ; juger d’abord la sécurité et le drainage.","checks":["Suivre le parcours des rejets","Vérifier siphon, relevage et alarme","Rechercher corrosion et débordements","Examiner les règles d’assainissement"],"evidence":["Plan EU","Photos et essai de relevage","Règlement d’assainissement"],"sources":["1978"],"pending":"Prescriptions locales de rejet et neutralisation à obtenir ; pas de seuil de puissance universel pour neutraliser les condensats.","review":"à compléter"},"condensats":{"id":"condensats","title":"Traitement des condensats","nature":"Prescription à déterminer","scope":"Appareils à condensation","popup":"Vérifier matériau, évacuation et traitement selon la notice et les conditions de rejet.","detail":"Identifier les appareils raccordés, le siphon, le dispositif éventuel de neutralisation et les conditions d’entretien. Une chaudière à condensation ne suffit pas à imposer un équipement identique sur tous les sites. Relever l’acidité si une mesure est faite et sa méthode. Examiner le règlement d’assainissement et la notice du fabricant. Une pompe de condensats doit être analysée avec ses défauts, son débordement possible et ses asservissements.","checks":["Lire la notice et le règlement de rejet","Contrôler évacuation et siphon","Vérifier neutralisant et entretien"],"evidence":["Notice fabricant","Règlement assainissement","Rapport d’entretien"],"sources":[],"pending":"Aucun seuil universel de pH ou de puissance n’est validé ici pour conclure à l’obligation de neutralisation.","review":"à compléter"},"puisage":{"id":"puisage","title":"Robinet de puisage et protection des retours","nature":"Obligation conditionnelle","scope":"Eau destinée à la consommation humaine","popup":"Identifier l’usage du robinet et les risques de retour d’eau, notamment avec un flexible.","detail":"Le choix d’une protection dépend du fluide susceptible de revenir, du branchement et de son usage. Un robinet dédié au lavage d’un local et muni d’un flexible peut présenter un risque différent d’un point de puisage ordinaire. Le libellé « Clapet HA » doit rester une référence de constat tant que la protection appropriée n’a pas été déterminée. Vérifier la date et le champ d’application du texte de protection des retours, puis la classification de risque dans le référentiel applicable.","checks":["Identifier usages et flexibles","Relever type de protection et sens","Vérifier accessibilité et entretien"],"evidence":["Schéma EF","Référence protection","Analyse de risque"],"sources":["retour"],"pending":"Contenu technique du texte de 2021 et avis sur les dispositifs, NF EN 1717 et règles locales à consulter pour choisir HA, EA, BA ou surverse.","review":"à compléter"},"coupuregaz":{"id":"coupuregaz","title":"Coupure combustible extérieure","nature":"Obligation conditionnelle","scope":"Installations avec alimentation combustible","popup":"Vérifier accessibilité, repérage et effet réel de la coupure depuis une position adaptée.","detail":"Distinguer coupure générale extérieure, organes de sécurité de la rampe gaz et organe propre à l’appareil. Relever les équipements réellement présents et les conditions de réarmement. Les exigences ICPE et gaz habitation ne se remplacent pas. Deux électrovannes ne démontrent pas une chaîne de sécurité correcte : comparer leur montage et leurs commandes au dossier. La présence d’un coffret ou d’un verre dormant doit être évaluée par rapport à la solution retenue, sans imposer un modèle de coffret à toute installation.","checks":["Identifier les organes et leur fonction","Vérifier repérage et accès","Lire le schéma des asservissements","Demander les essais documentés"],"evidence":["Schéma gaz","Matrice causes-effets","Rapport d’essai"],"sources":["dc","gaz"],"pending":"La formule « à chaque accès » et le matériel exact doivent être reliés à la prescription réellement applicable.","review":"à compléter"},"coupureelec":{"id":"coupureelec","title":"Coupure électrique extérieure","nature":"Obligation conditionnelle","scope":"Installations électriques du local","popup":"Identifier les circuits arrêtés et ceux dont le maintien est prévu pour la sécurité.","detail":"Le contrôle porte sur l’accès à la commande, le repérage, la fonction et l’indépendance des circuits concernés. Lire le schéma pour déterminer les effets sur production, éclairage de secours, détection, ventilation et relevage. Un arrêt global peut interagir avec les autres sécurités ; l’essai se prépare avec l’exploitant. Les libellés Force/Lumière/Relevage décrivent une configuration métier et ne prouvent pas une obligation identique dans tous les locaux.","checks":["Lire le schéma et les repérages","Déterminer les circuits coupés","Vérifier la commande et les preuves d’essai"],"evidence":["Schéma électrique","Rapport de vérification","Essai tracé"],"sources":["elec","dc"],"pending":"Exigences détaillées de séparation et de maintien des circuits à déterminer avec les textes propres à l’installation.","review":"à compléter"},"rampegaz":{"id":"rampegaz","title":"Ligne et rampe gaz","nature":"Prescription réglementaire et constructeur","scope":"Chaudières et brûleurs gaz","popup":"Contrôler la ligne gaz avec la notice du brûleur et le dossier de l’installation.","detail":"Identifier vannes, filtre, pressostats, régulation de pression, manomètre et contrôle de flamme. Relever le gaz, les plages de pression et les références de matériel. L’absence d’un composant portant un nom différent peut correspondre à une fonction intégrée ; consulter la notice. La présence d’un filtre ou d’un manomètre n’autorise pas une conclusion sur l’étanchéité. Le libellé METRA « compteur par chaudière si Pu > 1 MW » doit être revu en distinguant puissance utile et thermique et en identifiant le fondement du comptage.","checks":["Lire la notice de la rampe","Comparer le schéma au montage","Vérifier les rapports d’étanchéité et essais","Identifier les plages de pression"],"evidence":["Notice brûleur","Schéma gaz","Compte rendu d’essai"],"sources":["gaz","dc"],"pending":"Validation du seuil et de la règle de comptage par chaudière avant affichage comme obligation.","review":"à compléter"},"armoire":{"id":"armoire","title":"Armoire électrique et protections","nature":"Obligation générale et prescription de conception","scope":"Lieux de travail et équipements techniques","popup":"Contrôler l’état apparent, les repérages et le rapport électrique. Une observation visuelle ne certifie pas l’installation.","detail":"Relever schéma, protections, câblage visible, enveloppe, ventilation, traces d’échauffement et disponibilité du rapport de vérification. Les protections se dimensionnent selon circuits et usages. Le « 30 % libre » constitue ici un critère à justifier par le cahier des charges ou la conception ; ne pas le présenter comme exigence universelle. La prise notée 220 V dans la trame doit être décrite par sa tension réelle et son circuit. Une protection différentielle ne se valide pas par la seule lecture d’une étiquette.","checks":["Lire le dernier rapport et les réserves","Comparer repérages et schéma","Observer enveloppe et échauffements","Identifier les circuits de prises"],"evidence":["Rapport électrique","Schéma daté","Photos armoire fermée et repérages"],"sources":["elec"],"pending":"Normes NF C 15-100, référentiels machine et règles des zones ATEX : éditions et dispositions pertinentes à consulter.","review":"à compléter"},"baes":{"id":"baes","title":"Éclairage de sécurité et BAES","nature":"Obligation conditionnelle","scope":"Cheminements et locaux concernés","popup":"Vérifier le système d’éclairage de sécurité, sa fonction et ses essais.","detail":"Identifier évacuation, ambiance ou intervention, puis les changements de direction, sorties et obstacles. La veilleuse d’un bloc ne suffit pas à démontrer son autonomie. Le critère « visible partout » doit être interprété selon le besoin de guidage et la conception, pas comme obligation de voir tous les blocs depuis tout point. Conserver les essais fonctionnels et d’autonomie, les dates et les défauts. Ne pas conclure qu’un BAES est toujours obligatoire au-dessus de chaque porte de toute sous-station.","checks":["Repérer les parcours","Identifier le type de bloc","Lire essais fonctionnels et autonomie","Vérifier pictogrammes"],"evidence":["Plan éclairage sécurité","Registre d’essais","Référence du bloc"],"sources":["entretien"],"pending":"Régime exact ERP, lieu de travail ou habitation et arrêté d’éclairage de sécurité à compléter avant prescription de nombre et emplacement.","review":"à compléter"},"eclairage":{"id":"eclairage","title":"Éclairage, rangement et circulation","nature":"Obligation générale et exploitation","scope":"Locaux techniques","popup":"Vérifier que les opérations et la lecture des appareils restent possibles en sécurité.","detail":"Observer les zones d’ombre au droit des commandes, les luminaires en défaut, les sols glissants et les obstacles. Enregistrer le matériel stocké et son lien avec l’exploitation. L’évaluation porte sur les tâches réelles et les risques. Une photographie avec flash ne démontre pas un éclairage suffisant. Les délais P2/P3 présents dans la bibliothèque sont des propositions d’exploitation ; ils ne remplacent pas l’action nécessaire face à un risque constaté.","checks":["Observer en lumière normale","Vérifier accès aux organes","Rechercher sols glissants et obstacles","Documenter les risques"],"evidence":["Photos sans flash","Liste des défauts","Consignes de maintenance"],"sources":["1978","entretien"],"pending":"","review":"contenu de cadrage vérifié"},"equipotentiel":{"id":"equipotentiel","title":"Mise à la terre et équipotentialité","nature":"Prescription à vérifier","scope":"Équipements et réseaux métalliques","popup":"Vérifier les liaisons et les mesures dans le rapport électrique.","detail":"Décrire conducteurs, connexions visibles et repérage. Une liaison peinte ou visible ne prouve pas sa continuité ni son efficacité. L’absence de fil distinct sur un chemin de câble ne suffit pas non plus à diagnostiquer l’ensemble sans connaître la conception. Demander le schéma et les résultats de mesures appropriées. Les travaux doivent être prescrits à partir du diagnostic électrique, avec le périmètre exact et le matériel concerné.","checks":["Comparer au schéma","Relever connexions dégradées","Lire les mesures et réserves du rapport"],"evidence":["Rapport électrique","Schéma terre","Photos"],"sources":["elec"],"pending":"Référentiel normatif et mesures de continuité à établir par le contrôle électrique compétent.","review":"à compléter"},"calorifuge":{"id":"calorifuge","title":"Calorifuge et isolation","nature":"Obligation conditionnelle et performance","scope":"Production et distribution de chaleur","popup":"Relever isolation, état, discontinuités et compatibilité avec le service et la sécurité incendie.","detail":"Identifier départs, retours, ECS, points chauds, vannes et brides. Vérifier les zones dépourvues d’isolation et les éléments démontables pour l’entretien. Le texte de 1978 prévoit le calorifugeage des générateurs et canalisations de fluide caloporteur avec une exception pour celles participant au chauffage des locaux traversés. Rechercher aussi les obligations contemporaines et les exigences contractuelles avant de classer systématiquement l’intervention comme simple amélioration.","checks":["Cartographier les manques","Identifier température et matériau","Vérifier état et démontabilité","Documenter la réaction au feu requise"],"evidence":["Photos","Mémoire technique isolation","Plan réseaux"],"sources":["1978"],"pending":"Échéances récentes de calorifugeage, classes d’isolation et cas d’exemption à intégrer selon le parc ciblé.","review":"à compléter"},"disconnection":{"id":"disconnection","title":"Protection EF chauffage et ECS","nature":"Obligation conditionnelle","scope":"Branchements d’eau et risques de retour","popup":"Choisir la protection selon le risque de retour et le fluide, puis contrôler le montage et l’entretien.","detail":"Distinguer appoint d’un circuit chauffage fermé avec additifs, alimentation ECS et alimentation de traitement d’eau. Renseigner les produits, la possibilité de mélange et le schéma hydraulique. Le seuil de puissance seul ne détermine pas toute protection. La bibliothèque parle de « disconnecteur EA » pour l’ECS : clarifier le type exact, EA désignant une famille de clapets dans le référentiel usuel. Avant de demander BA, EA ou surverse, justifier la classe de risque et vérifier les conditions de pose.","checks":["Identifier fluide et additifs","Lire la référence de protection","Vérifier sens, évacuation et accessibilité","Demander l’entretien"],"evidence":["Schéma EF","Analyse du risque retour","Référence et rapport de contrôle"],"sources":["retour"],"pending":"Choix technique et fréquence à valider avec le texte complet de 2021, ses avis, la norme applicable et les prescriptions du service d’eau.","review":"à compléter"},"compteurs":{"id":"compteurs","title":"Compteurs et index","nature":"Mesure et exploitation","scope":"Gaz, énergie, EF, appoint et sous-stations","popup":"Relever un index avec son unité, son identifiant et l’heure ; distinguer valeur du jour et historique.","detail":"Vérifier numéro du compteur, multiplicateur, unité, destination et périmètre. Pour un compteur d’appoint, confirmer qu’il compte l’appoint attendu et non une consommation partagée. Pour le gaz, ne pas convertir m³ en énergie avec un coefficient constant universel. Pour le réseau de chaleur, garder la limite contractuelle primaire/secondaire. Un compteur manquant peut relever du contrat, du suivi énergétique ou d’une obligation spécifique ; ne pas inventer une obligation à partir de la seule trame.","checks":["Photographier numéro et index","Contrôler unité et multiplicateur","Identifier les remplacements ou remises à zéro","Rattacher au bon réseau"],"evidence":["Photo de lecture","Historique","Fiche compteur et contrat"],"sources":["trames"],"pending":"","review":"contenu de cadrage vérifié"},"pression":{"id":"pression","title":"Pressions et températures chauffage","nature":"Prescription constructeur et conception","scope":"Circuits chauffage et primaire","popup":"Comparer les valeurs aux plages du dossier de conception et des appareils.","detail":"Documenter régime chaud/froid, hauteur statique, vase d’expansion, pompe et pression maximale admissible des composants. Une valeur de pression unique telle que 1,5 bar ne convient pas à tous les bâtiments. Relever température extérieure, départ et retour simultanément pour interpréter l’écart. Une pression satisfaisante peut coexister avec un défaut d’expansion. Le contrôle des accessoires de sécurité reste séparé de la simple mesure.","checks":["Relever chaud/froid et état des pompes","Comparer au dossier","Vérifier les instruments et leurs unités","Rechercher appoints excessifs"],"evidence":["Note hydraulique","Plaques PS et températures","Mesures datées"],"sources":["esp"],"pending":"","review":"contenu de cadrage vérifié"},"ph":{"id":"ph","title":"pH et qualité d’eau technique","nature":"Prescription constructeur","scope":"Circuits fermés chauffage","popup":"Comparer le pH à la plage prescrite pour les matériaux et le traitement réellement présents.","detail":"Identifier acier, cuivre, aluminium, composants mixtes, eau d’appoint et produits de traitement. Enregistrer la méthode, la température, l’instrument et la date. La valeur cible dépend de la compatibilité de l’ensemble et ne doit pas être un seuil réglementaire global METRA. Une anomalie appelle une analyse du circuit et des appoints avant une modification de dosage. Rechercher conductivité, dureté et autres paramètres demandés par les notices lorsque le diagnostic le nécessite.","checks":["Identifier matériaux et produits","Vérifier la procédure de prélèvement","Comparer à la notice","Vérifier l’instrument"],"evidence":["Analyse d’eau","Notice chaudière","Fiche produit"],"sources":[],"pending":"Plages spécifiques à chaque constructeur et traitement à intégrer ; aucun pH universel validé.","review":"à compléter"},"traitement":{"id":"traitement","title":"Filtration, pot d’introduction et produits","nature":"Prescription technique et exploitation","scope":"Chauffage et traitement d’eau","popup":"Vérifier la fonction, la compatibilité et l’entretien du traitement prévu.","detail":"Identifier filtre, désemboueur, pot, doseuse et points d’injection, leur position et leur relation au débit. Le désemboueur magnétique sur 100 % du débit est une solution technique à apprécier, pas une exigence générale pour tout circuit. Les produits doivent être compatibles avec les matériaux, les usages et la notice. Documenter dosage, quantités, contrôle et entretien. Un système en dérivation peut être justifié ; une absence de filtre ne vaut pas automatiquement non-conformité.","checks":["Comparer au schéma de conception","Vérifier entretien et pertes de charge","Lire la fiche technique produit","Documenter le dosage"],"evidence":["Schéma hydraulique","Notice et fiche produit","Rapport d’entretien"],"sources":[],"pending":"Obligations techniques particulières à valider selon matériel, eau et contrat.","review":"à compléter"},"retention":{"id":"retention","title":"Rétention et produits chimiques","nature":"Obligation conditionnelle et maîtrise des risques","scope":"Stockage de produits","popup":"Identifier les produits et prévoir une rétention compatible selon le risque et les prescriptions.","detail":"Relever emballages, quantités, incompatibilités, risque de débordement et devenir d’une fuite. Un bac présent doit être approprié au produit et aux quantités stockées. Une règle de capacité ne se déduit pas du seul intitulé « bac de rétention » ; la prescription dépend du classement et du contexte. Conserver les fiches de données de sécurité et vérifier l’étiquetage. La doseuse et son circuit d’injection présentent des risques distincts du stockage.","checks":["Lire les FDS","Relever les volumes stockés","Vérifier compatibilité et absence de fuite","Identifier les voies de rejet"],"evidence":["FDS","Inventaire produits","Photos bac et stockage"],"sources":["dc"],"pending":"Dimensionnement de rétention à établir avec la prescription du régime et les produits du site.","review":"à compléter"},"fumees":{"id":"fumees","title":"Conduits de fumée","nature":"Prescription réglementaire et dimensionnement","scope":"Appareils à combustion","popup":"Vérifier compatibilité appareil/conduit, état, étanchéité et justificatif de dimensionnement.","detail":"Relever type de chaudière, condensation, pression de fonctionnement, combustible, tracé et matériau. La section dépend du système complet et ne se calcule pas avec la seule puissance totale. Demander la note de dimensionnement et les caractéristiques du conduit. Une chaudière à condensation n’impose pas automatiquement un tubage d’un conduit déjà approprié. Le thermomètre et le seuil de contrôle doivent être rattachés au régime de l’appareil. Une visite visuelle ne confirme pas l’étanchéité interne ou le tirage de tous les conduits.","checks":["Identifier appareils raccordés","Relever matériau et corrosion","Lire note de dimensionnement","Demander entretien et vérification"],"evidence":["Note fumisterie","Notice chaudière","Rapport ramonage et contrôle"],"sources":["1978","gaz"],"pending":"NF EN 13384, DTU fumisterie et seuil du thermomètre > 400 kW à vérifier dans le domaine exact avant automatisation.","review":"à compléter"},"soupapes":{"id":"soupapes","title":"Soupapes et accessoires de sécurité","nature":"Prescription de conception et suivi ESP","scope":"Chaudières, ballons et circuits","popup":"Vérifier nombre, capacité, tarage, montage et évacuation avec le dossier constructeur.","detail":"Identifier pression maximale admissible de chaque composant, débit requis et protection effective de chaque volume isolable. Le nombre de soupapes seul ne démontre pas la sécurité ; deux soupapes ne sont pas une exigence universelle de tous les générateurs. Examiner obstruction, isolement possible, écoulement et destination sûre. Le tarage se choisit selon la conception ; ne pas le fixer automatiquement à la pression habituelle lue au manomètre. Les échéances de suivi ESP dépendent de la catégorie et du dispositif de suivi applicable.","checks":["Lire PS et tarage","Comparer au dossier constructeur","Repérer isolement et obstruction","Vérifier contrôles et évacuation"],"evidence":["Notice et dossier ESP","Plaques et certificats soupapes","Rapports de contrôle"],"sources":["esp"],"pending":"Validation de la capacité, du nombre et des règles de montage avec le référentiel de conception applicable.","review":"à compléter"},"ecs_temp":{"id":"ecs_temp","title":"Températures ECS et brûlures","nature":"Obligation conditionnelle","scope":"ECS avec points d’usage concernés","popup":"Distinguer stockage, distribution, retour et puisage ; appliquer les limites au point concerné.","detail":"Au puisage, l’article 36 fixe 50 °C maximum pour la toilette, 60 °C dans les autres pièces et un cas particulier signalé jusqu’à 90 °C en cuisines et buanderies ERP. Avec points à risque et volume de distribution > 3 L, le réseau doit rester ≥ 50 °C hors tubes terminaux limités à 3 L. Pour stockage ≥ 400 L hors préchauffage : ≥ 55 °C à la sortie, ou traitement thermique quotidien conforme à l’annexe. La consigne historique 58–60 °C est un réglage d’exploitation à justifier, pas une limite universelle.","checks":["Identifier le point exact de mesure","Mesurer stockage, départ, retours et puisages","Vérifier les volumes","Documenter mitigeage et protections"],"evidence":["Schéma ECS","Volumes","Mesures horodatées","Paramètres de régulation"],"sources":["ecs"],"pending":"","review":"contenu de cadrage vérifié"},"ecs_cycle":{"id":"ecs_cycle","title":"Cycle thermique et prévention légionelles","nature":"Obligation conditionnelle et protocole","scope":"ECS concernée par l’article 36","popup":"Un cycle ne suffit pas à prouver la maîtrise sanitaire. Vérifier le couple température/durée et les points atteints.","detail":"Distinguer la solution réglementaire de traitement quotidien du stockage, la stratégie habituelle de production et une désinfection ponctuelle du réseau. Le bouton « anti-légionellose » d’un régulateur ne démontre pas que chaque ballon et branche a atteint les conditions attendues. Documenter le protocole, les preuves, la protection contre les brûlures et les mesures après intervention. La bonne température de stockage ne prouve pas l’absence de colonisation du réseau.","checks":["Identifier l’objectif du cycle","Vérifier enregistrements et volumes concernés","Vérifier protections aux puisages","Rattacher au protocole sanitaire"],"evidence":["Protocole","Courbes d’enregistrement","Rapport sanitaire"],"sources":["ecs","legio"],"pending":"Couples exacts de l’annexe 1 et protocole de désinfection à intégrer après validation sanitaire ; aucun déclenchement conseillé automatiquement depuis une fenêtre d’aide.","review":"à compléter"},"ecs_surveillance":{"id":"ecs_surveillance","title":"Carnet sanitaire et analyses","nature":"Obligation conditionnelle","scope":"Établissements visés par l’arrêté du 1er février 2010","popup":"Vérifier le fichier sanitaire et le programme de surveillance adapté au type d’établissement.","detail":"L’arrêté de 2010 vise les établissements de santé, certaines structures d’accueil et les ERP avec points d’usage à risque. Il prévoit la traçabilité, des températures et analyses aux points et fréquences des annexes. Pour les établissements hors santé concernés, l’annexe 2 prévoit notamment des températures mensuelles et des analyses annuelles aux points désignés. La cible générale est < 1 000 UFC/L de Legionella pneumophila aux points à risque ; les patients particulièrement vulnérables relèvent d’une exigence spécifique. Ne pas étendre ce programme sans analyse à toute chaufferie d’habitation.","checks":["Identifier catégorie et usages à risque","Lire plan de surveillance","Vérifier prélèvements et résultats","Vérifier actions et traçabilité"],"evidence":["Fichier sanitaire","Rapports laboratoire","Plan des points","Relevés températures"],"sources":["legio"],"pending":"","review":"contenu de cadrage vérifié"},"ecs_accessoires":{"id":"ecs_accessoires","title":"Ballons, prélèvements et manchettes","nature":"Prescription à déterminer","scope":"Production et distribution ECS","popup":"Vérifier accessibilité de nettoyage, vidange, prélèvements et contrôle des matériaux.","detail":"Relever les matériaux du réseau, les accès internes prévus par le fabricant, les points de vidange et les dispositifs de prélèvement du programme sanitaire. Une manchette témoin répond à un suivi de corrosion dans certains systèmes et ne constitue pas une obligation de tous les réseaux ECS. Le seuil « trou d’homme > 1 000 L » de la bibliothèque doit être justifié par le référentiel applicable. Un robinet de prélèvement doit correspondre à l’analyse et au protocole retenus. Documenter la possibilité réelle de nettoyage du ballon.","checks":["Identifier matériaux et volumes","Lire la notice de nettoyage","Vérifier les points de prélèvement","Consulter le programme sanitaire"],"evidence":["Notice ballon","Schéma ECS","Protocole de prélèvement"],"sources":["legio"],"pending":"Référentiels des manchettes et seuil du trou d’homme à confirmer ; aucune obligation universelle validée sur ces deux points.","review":"à compléter"},"ecs_dosage":{"id":"ecs_dosage","title":"Traitement et injection ECS","nature":"Prescription sanitaire et constructeur","scope":"Eau sanitaire","popup":"Vérifier l’adéquation sanitaire du traitement, le dosage et les contrôles associés.","detail":"Identifier la nature du traitement, sa finalité, les produits utilisés et les conditions d’emploi pour l’eau distribuée. Un niveau de bidon correct ne prouve pas l’injection. Vérifier la pompe, le point d’injection, les analyses nécessaires et les précautions de stockage. Ne pas conseiller de dosage ou de remplacement de produit sans notice et validation appropriées. Le traitement d’un circuit fermé de chauffage ne se transpose pas à l’ECS.","checks":["Identifier produit et usage","Vérifier circuit et point d’injection","Lire le suivi de dosage","Examiner analyses et stockage"],"evidence":["Fiche produit","Notice doseuse","Analyses","Schéma injection"],"sources":[],"pending":"Autorisation d’usage et limites sanitaires du produit à documenter avant prescription.","review":"à compléter"},"adoucisseur":{"id":"adoucisseur","title":"Adoucisseur","nature":"Prescription constructeur et exploitation","scope":"EF technique ou sanitaire selon branche","popup":"Identifier le réseau alimenté et vérifier traitement, régénération et entretien.","detail":"Relever référence, volume résine, réglages, by-pass, filtre, bac à sel et évacuation. Mesurer la dureté amont/aval selon procédure et distinguer les usages techniques et sanitaires. Un manque de sel est un défaut d’entretien ; l’absence d’un adoucisseur n’est pas en soi une non-conformité universelle. Le by-pass sert à maintenir le service pendant la maintenance et doit être analysé avec les risques de mélange. Vérifier propreté, stagnation et conditions de régénération.","checks":["Identifier les branches desservies","Lire les réglages et la notice","Vérifier sel et état","Mesurer la dureté si prévu"],"evidence":["Notice","Mesures TH","Rapport d’entretien","Schéma EF"],"sources":[],"pending":"Valeurs cibles TH et prescriptions sanitaires à déterminer selon usage et constructeur.","review":"à compléter"},"distribution":{"id":"distribution","title":"Distribution hydraulique","nature":"Prescription technique et exploitation","scope":"Chauffage et ECS","popup":"Décrire matériaux, circuits, organes, isolation et équipements sur aller/retour.","detail":"Identifier les branches desservies, les organes d’équilibrage, vannes, circulateurs, émetteurs et mitigeurs. Relever fuites, corrosion, supportage et accessibilité. Vérifier la cohérence avec le schéma à jour et les notices ; aucune température ou vitesse universelle ne doit être déduite du seul type d’émetteur. En ECS, relier le contrôle aux mesures sanitaires et aux volumes ; en chauffage, relier les observations à la conception et à la régulation. Documenter les réseaux mixtes et les interfaces de matériaux.","checks":["Comparer schéma et terrain","Identifier chaque branche","Relever matériaux et organes","Vérifier supportage et accès"],"evidence":["Schéma","Photos","Notice et dossier hydraulique"],"sources":[],"pending":"","review":"contenu de cadrage vérifié"},"regulation":{"id":"regulation","title":"Régulation et courbe de chauffe","nature":"Exploitation et conception","scope":"Chauffage, cascade et réseaux","popup":"Comparer consignes, courbe, horaires et fonctionnement réel au besoin du bâtiment.","detail":"Enregistrer température extérieure, points de courbe, température de non-chauffe et programmes avec leur contexte. La courbe dépend des émetteurs, de l’enveloppe et du confort attendu ; aucun triplet de températures n’est imposé à tous les sites. Vérifier la cohérence des sondes et l’effet réel des commandes. La cascade doit être analysée avec les priorités, alternances et limites constructeur. En réseau de chaleur, distinguer réglages primaires et secondaires et respecter les obligations du contrat de fourniture.","checks":["Lire les consignes et horaires","Comparer sondes et mesures","Vérifier commandes et modes forcés","Identifier les limites constructeur"],"evidence":["Captures régulateur","Mesures","Contrat et notices"],"sources":[],"pending":"","review":"contenu de cadrage vérifié"},"rcu":{"id":"rcu","title":"Sous-stations et limite primaire secondaire","nature":"Réglementation conditionnelle et contrat","scope":"Réseaux de chaleur","popup":"Identifier les limites de propriété et de prestation avant de qualifier un défaut.","detail":"Une sous-station sans combustion ne doit pas recevoir automatiquement les prescriptions gaz ou fumées d’une chaufferie. La trame partage certains libellés ICPE : conserver un état Sans objet justifié lorsque l’équipement ou le risque est absent. Les classements Primaire/Secondaire du logiciel sont des conventions métier ; ils ne changent pas le domaine d’application légal ni les responsabilités du contrat. Identifier fluide, températures, pressions, échangeur, soupapes et ventilation. Les accès de sous-station relèvent des dispositions spécifiques du titre II de 1978 lorsque applicable.","checks":["Identifier la limite de livraison","Lire contrat et schéma","Distinguer vapeur, eau surchauffée et eau chaude","Justifier les contrôles sans objet"],"evidence":["Contrat réseau","Schéma primaire secondaire","Plaques échangeurs","Dossier sous-station"],"sources":["1978","sstvent","trames"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_identite":{"id":"vmc_identite","title":"Identifier le système VMC","nature":"Cadrage réglementaire","scope":"Ventilation de logements ou autre usage","popup":"Identifier le type de ventilation, les bâtiments et les bouches avant de choisir les valeurs de contrôle.","detail":"Distinguer simple flux, double flux, autoréglable, hygroréglable, ventilation naturelle et VMC gaz. La trame actuelle décrit surtout les caissons et réseaux communs. La conformité de ventilation d’un logement ne se conclut pas uniquement au caisson : entrées d’air, passage entre pièces, bouches et débits sont à examiner. Pour les systèmes modulés, demander le document technique correspondant. L’arrêté de 1982 concerne l’aération des logements ; il ne remplace pas les règles des bureaux ou locaux de travail.","checks":["Identifier usage et système","Relever bouches et caissons","Collecter le dossier de conception","Définir le périmètre de mesures"],"evidence":["Plans et notice","Avis technique applicable","Relevé des bouches"],"sources":["vmc"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_acces":{"id":"vmc_acces","title":"Accès caisson et travail en hauteur","nature":"Obligation conditionnelle de sécurité","scope":"Toitures et accès de maintenance","popup":"Vérifier cheminement, protections collectives et conditions réelles de maintenance.","detail":"Documenter escaliers, trappes, échelles, cheminements, toiture fragile et proximité des rives. Les règles de travaux temporaires en hauteur imposent une prévention des chutes adaptée ; une ligne de vie visible ne suffit pas à démontrer l’accès sûr. Les protections collectives et l’organisation de l’intervention doivent être examinées. La fiche relève le risque et les justificatifs ; elle ne recommande pas une intervention en hauteur sur la seule base de photos.","checks":["Tracer le chemin d’accès","Identifier les risques de chute","Vérifier protections et documents","Identifier les zones fragiles"],"evidence":["Plan de prévention","Dossier protections","Photos depuis accès sûr"],"sources":["hauteur"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_caisson":{"id":"vmc_caisson","title":"État et fonctionnement du caisson","nature":"Entretien et performance","scope":"Caissons VMC","popup":"Observer corrosion, bruit, vibrations et extraction réelle avec le système en fonctionnement.","detail":"Décrire défauts d’enveloppe, moteur, fixation et bruit avec localisation. Un ventilateur qui tourne n’assure pas forcément le débit attendu aux bouches. Relever les mesures disponibles, le mode de commande et les conditions de fonctionnement. Distinguer une corrosion superficielle d’une perforation ou instabilité. Une conclusion « fonctionnement satisfaisant » doit préciser les limites de l’essai. Le nettoyage doit respecter la notice et l’accès prévu.","checks":["Observer fonctionnement et vibrations","Vérifier fixation et corrosion","Documenter mesures disponibles","Lire maintenance et défauts"],"evidence":["Photos","Mesures","Rapport maintenance"],"sources":["entretien"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_courroie":{"id":"vmc_courroie","title":"Courroie et transmission","nature":"Obligation conditionnelle et entretien","scope":"Extracteurs collectifs concernés","popup":"Contrôler l’état, la tension et la transmission. Identifier le besoin de courroie de secours.","detail":"Pour les installations mécaniques collectives de logements relevant de l’article 10 de 1982, l’extracteur à courroie doit comporter une courroie supplémentaire de secours. Un entraînement direct justifie Sans objet pour la courroie. Relever craquelures, usure, glissement et fixation des protections. Les réglages de tension et d’alignement suivent la notice. Distinguer présence d’une courroie dans un stock identifié et simple affirmation sans preuve.","checks":["Identifier entraînement direct ou courroie","Vérifier état et secours","Lire la notice et l’entretien"],"evidence":["Photo transmission à l’arrêt sécurisé","Référence courroie","Stock secours"],"sources":["vmc"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_coupure":{"id":"vmc_coupure","title":"Coupure et consignation VMC","nature":"Sécurité d’intervention","scope":"Caissons VMC","popup":"Identifier la coupure et les conditions de consignation avant maintenance.","detail":"Vérifier le repérage du bon caisson, l’accessibilité de la commande et les risques de redémarrage automatique. Un interrupteur visible n’établit pas à lui seul une consignation adaptée. Lire schéma, notice et procédure. La télégestion ou un horaire automatique peut provoquer un redémarrage ; la fiche doit rappeler la nécessité d’un protocole validé et d’une intervention autorisée. Les défauts électriques sont rattachés au rapport de vérification.","checks":["Identifier la commande du bon caisson","Vérifier le schéma","Lire les procédures","Identifier commandes distantes"],"evidence":["Schéma","Procédure de consignation","Rapport électrique"],"sources":["elec","entretien"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_reseau":{"id":"vmc_reseau","title":"Manchettes, traînasses et étanchéité","nature":"Prescription technique et entretien","scope":"Réseaux aérauliques","popup":"Observer l’étanchéité, le supportage et l’accessibilité des réseaux.","detail":"Relever manchettes déchirées, déboîtements, corrosion, percements et joints. Une fuite sur un réseau en dépression peut réduire l’extraction utile sans soufflage visible. Le supportage doit être adapté à la géométrie et aux charges ; aucun nombre universel de pieds ne se déduit de la trame. Vérifier les interfaces avec les parois et le dossier incendie. Une inspection visuelle ne remplace pas une campagne de mesure d’étanchéité ou de débit.","checks":["Localiser les défauts","Vérifier fixation et raccords","Comparer au dossier","Identifier les traversées"],"evidence":["Photos","Plan du réseau","Mesures si disponibles"],"sources":[],"pending":"Référentiels DTU ventilation et exigences au feu à vérifier selon système et bâtiment.","review":"à compléter"},"vmc_nettoyage":{"id":"vmc_nettoyage","title":"Nettoyage des caissons et colonnes","nature":"Entretien et contrat","scope":"Réseaux VMC","popup":"Vérifier état observable et justificatifs de nettoyage, avec le périmètre réellement traité.","detail":"Un justificatif doit préciser date, méthode, caissons, colonnes, bouches et zones inaccessibles. La propreté du caisson ne prouve pas celle des colonnes. La périodicité dépend des obligations du système, de la notice et du contrat ; ne pas afficher un intervalle général non justifié. Prévoir un contrôle de fonctionnement après intervention et une traçabilité des parties non traitées. Les trappes doivent permettre l’entretien prévu par la conception.","checks":["Lire le périmètre du rapport","Observer les parties accessibles","Repérer zones non traitées","Documenter contrôle après nettoyage"],"evidence":["Rapport nettoyage","Photos","Notice et contrat"],"sources":["entretien"],"pending":"Périodicités spécifiques VMC gaz et prescriptions du bâtiment à compléter.","review":"à compléter"},"vmc_registres":{"id":"vmc_registres","title":"Registres et trappes","nature":"Prescription technique","scope":"Réseaux VMC","popup":"Vérifier les organes de réglage et accès de visite prévus, sans imposer un équipement absent du projet.","detail":"Identifier l’usage du registre, sa position, son accessibilité et son effet sur l’équilibrage. Une absence ne constitue un écart que si la fonction est requise et non assurée autrement. Vérifier les trappes nécessaires au nettoyage et leur fermeture. Conserver les réglages avant intervention et comparer les mesures aux valeurs prévues. Les composants ne doivent pas dégrader les exigences incendie du réseau.","checks":["Identifier la fonction","Comparer au plan","Vérifier accès et état","Documenter les réglages"],"evidence":["Plan","Dossier réglages","Photos"],"sources":[],"pending":"Référentiel de conception et exigences techniques à valider pour le système installé.","review":"à compléter"},"vmc_rejet":{"id":"vmc_rejet","title":"Chapeau et rejet extérieur","nature":"Obligation de fonctionnement et prescription technique","scope":"Sorties VMC","popup":"Vérifier que le rejet fonctionne sans renvoi vers les logements et respecte la conception.","detail":"L’article 10 de 1982 traite du rejet mécanique sans refoulement ni renvoi vers les logements. Un chapeau est une solution de conception à contrôler selon le système ; son absence ne doit pas conduire automatiquement à prescrire un modèle qui pourrait augmenter les pertes de charge. Relever fixations, corrosion, obstacles et prises d’air voisines. La règle ICPE concernant certains débouchés ne se transpose pas aux rejets VMC.","checks":["Identifier le terminal prévu","Observer les prises voisines","Vérifier fixation et obstruction","Lire la note aéraulique"],"evidence":["Photos toiture","Plan de rejet","Notice terminal"],"sources":["vmc"],"pending":"","review":"contenu de cadrage vérifié"},"vmc_gestion":{"id":"vmc_gestion","title":"Pressostat et télégestion VMC","nature":"Prescription technique et cas réglementaires spécifiques","scope":"Ventilation et VMC gaz","popup":"Vérifier la fonction du pressostat et le report de défaut ; identifier séparément une VMC gaz.","detail":"Un pressostat contrôle une grandeur liée au fonctionnement ; il ne mesure pas tous les débits des logements. Vérifier seuil, tuyaux, raccordements et report. Une télégestion absente peut être une amélioration contractuelle plutôt qu’une non-conformité. En VMC gaz, la sécurité collective et les appareils raccordés nécessitent un dossier spécifique ; ne pas reprendre les commentaires d’une VMC ordinaire. Identifier les essais prévus et l’intervention qualifiée nécessaire.","checks":["Identifier système et fonction","Lire réglages et schéma","Demander rapport d’essai","Vérifier le report jusqu’au destinataire"],"evidence":["Notice","Schéma sécurité","Rapport essai","Dossier VMC gaz"],"sources":["gaz"],"pending":"Textes spécifiques DSC/VMC gaz, maintenance et protocoles d’essai à intégrer avant décision de conformité.","review":"à compléter"},"vmc_debits":{"id":"vmc_debits","title":"Débits de ventilation des logements","nature":"Obligation conditionnelle et mesures","scope":"Logements dans le domaine de l’arrêté de 1982","popup":"Mesurer aux points pertinents et comparer au système autorisé, pas seulement au débit nominal du caisson.","detail":"L’arrêté distingue les débits atteignables par pièce, les débits réduits et les systèmes modulés. Le nombre de pièces principales et le type de système sont indispensables. Une mesure doit préciser l’appareil, le point, le mode de bouche et les conditions. Les avis techniques des systèmes hygroréglables doivent être utilisés pour leur configuration. Les tables et le calcul d’aire-débit au chapitre Formules sont des aides ; le débit total nominal du ventilateur ne prouve pas la conformité de chaque logement.","checks":["Identifier pièces et bouches","Relever le mode de fonctionnement","Mesurer avec une méthode adaptée","Comparer au référentiel du système"],"evidence":["Campagne débits","Plan logements","Avis technique"],"sources":["vmc"],"pending":"","review":"contenu de cadrage vérifié"},"pa_organisation":{"id":"pa_organisation","title":"Préparer les essais de pré-allumage","nature":"Exploitation et sécurité","scope":"Visites de préparation saisonnière","popup":"Définir les essais du jour, les intervenants, les prérequis et les équipements concernés.","detail":"Les données patrimoniales peuvent être reprises, mais les résultats des essais et mesures doivent être refaits. Identifier énergie disponible, conditions d’accès, autorisations d’intervention et dossier de sécurité. Les presets « Satisfaisant » décrivent un constat observé ; ils ne valent pas réception réglementaire de toute l’installation. Prévoir Non réalisé ou Non visible avec motif et suite à donner. Distinguer contrôle visuel, manœuvre, essai fonctionnel et mesure.","checks":["Définir protocole et périmètre","Identifier l’exploitant","Vérifier prérequis","Tracer les essais et ceux non réalisés"],"evidence":["Fiche d’essai","Notices","Compte rendu de visite"],"sources":["trames","entretien"],"pending":"","review":"contenu de cadrage vérifié"},"pa_allumage":{"id":"pa_allumage","title":"Essais chaudières et brûleurs","nature":"Prescription constructeur et sécurité","scope":"Pré-allumage production","popup":"Observer la séquence autorisée, la stabilité de fonctionnement et les mises en sécurité.","detail":"Le dossier couvre test allumage, présence de flamme, montée en température, électrovanne et électrode. Chaque résultat doit identifier chaudière ou brûleur, date, conditions et opérateur. Ne pas proposer de contourner une sécurité ni de multiplier des réarmements sur une anomalie. Un allumage réussi ne prouve pas la combustion correcte ou tous les organes de sécurité. Rattacher l’analyse à la notice et aux mesures prévues. Le contenu d’aide guide le constat et la documentation, sans remplacer une procédure d’intervention.","checks":["Identifier appareil et protocole","Documenter défauts et mises en sécurité","Relever mesures prévues","Vérifier les comptes rendus"],"evidence":["Notice","Fiche d’essai","Mesures combustion si réalisées"],"sources":["entretien","esp"],"pending":"","review":"contenu de cadrage vérifié"},"pa_pompes":{"id":"pa_pompes","title":"Essais pompes et circulateurs","nature":"Prescription constructeur et exploitation","scope":"Production, chauffage et ECS","popup":"Vérifier démarrage, débit utile, sens et alternance selon la conception.","detail":"Observer bruit, vibrations, fuites, défauts, variateur et fonctionnement de la pompe de secours. Un variateur sous tension n’établit pas la circulation. Un fonctionnement simultané peut être normal selon le dimensionnement ; ne pas appliquer systématiquement le preset « anormal ». Pour l’ECS, vérifier l’effet de la circulation sur les températures et les branches. Documenter commande locale/distante, mode automatique et limitations de l’essai.","checks":["Identifier pompe et mode","Vérifier effet hydraulique","Documenter alternance","Relever bruit, fuite et défauts"],"evidence":["Fiche essai","Notice","Mesures pression et températures"],"sources":[],"pending":"","review":"contenu de cadrage vérifié"},"pa_vannes":{"id":"pa_vannes","title":"Essais vannes et servomoteurs","nature":"Prescription constructeur","scope":"Chauffage et ECS","popup":"Comparer commandes, course et effet hydraulique selon le montage.","detail":"Observer ouverture, fermeture, accouplement, retours de position et temps de course prescrits. La position du servomoteur ne prouve pas celle de l’obturateur si l’accouplement est défaillant. Documenter les modes manuels et rétablir l’état prévu en fin d’essai. Une vanne trois voies peut fonctionner en mélange ou répartition ; interpréter les températures avec le schéma. Les contrôles de régulation se rattachent aux sondes et aux programmes du site.","checks":["Lire schéma et notice","Observer course et accouplement","Comparer commande et réponse","Documenter l’état final"],"evidence":["Schéma","Notice","Compte rendu essai"],"sources":[],"pending":"","review":"contenu de cadrage vérifié"},"pa_sst":{"id":"pa_sst","title":"Essais des sous-stations","nature":"Exploitation et contrat","scope":"SST, commerces, bureaux et église","popup":"Identifier la sous-station et les branches ; contrôler chauffage, ECS et traitement présents.","detail":"Les rubriques répétables SST 1 à 10 et autres bâtiments décrivent un modèle, pas une obligation d’avoir ces installations. Le patrimoine réel doit déterminer les sections actives. Rattacher chaque pompe, vanne, doseuse et régulation au bon local et au bon réseau. Préciser qui intervient côté primaire et secondaire. Un essai positif d’une SST ne valide pas les autres. Les index et températures restent des valeurs du jour, même si les noms et références sont repris.","checks":["Rattacher chaque essai au bon local","Vérifier les branches","Documenter les limites contractuelles","Identifier les contrôles sans objet"],"evidence":["Plan site","Contrat","Fiches d’essai par SST"],"sources":["trames"],"pending":"","review":"contenu de cadrage vérifié"},"conclusion":{"id":"conclusion","title":"Conclusion et réserves","nature":"Synthèse professionnelle","scope":"Toutes les trames","popup":"Séparer faits, contrôles non réalisés, écarts justifiés et actions restantes.","detail":"Une conclusion de préparation saisonnière doit préciser installations couvertes, essais réalisés, limites et actions préalables. La notion « prêt » nécessite une décision responsable documentée ; elle ne se déduit pas automatiquement d’un taux de progression. Les réserves restent dans leur visite et leur trame. P2, P3 et conformité décrivent des postes métier et contractuels ; les délais et coûts de la bibliothèque ne sont pas des délais légaux. Distinguer correction technique, document à fournir et amélioration.","checks":["Lister les points non testés","Relier les réserves aux preuves","Justifier les obligations invoquées","Distinguer contrat et droit"],"evidence":["Compte rendu signé","Preuves liées","Plan d’actions"],"sources":["trames"],"pending":"","review":"contenu de cadrage vérifié"},"equipements":{"id":"equipements","title":"Inventaire des équipements","nature":"Documentation métier","scope":"Toutes les trames","popup":"Identifier équipement, local, réseau, référence et caractéristiques avec preuve.","detail":"Relever marque, modèle, série, année, puissance et valeurs limites selon la plaque. Distinguer valeur lue, importée, estimée et absente. Le catalogue fabricant aide à identifier mais ne prouve pas que l’équipement posé possède exactement les mêmes options. Filtrer les équipements par trame et conserver l’identité patrimoniale. Pour le réseau de chaleur, rattacher le périmètre propre à la trame sans changer celui des autres visites.","checks":["Photographier la plaque","Vérifier identité et local","Renseigner unités","Identifier source des caractéristiques"],"evidence":["Plaque","Notice","Fiche équipement"],"sources":["trames"],"pending":"","review":"contenu de cadrage vérifié"},"photos":{"id":"photos","title":"Photos et preuves","nature":"Documentation métier","scope":"Toutes les visites","popup":"Rattacher chaque photo au constat, au local et à la visite correspondante.","detail":"Prévoir une vue de contexte, une vue du défaut et une vue de plaque ou de mesure. Ajouter date, lieu, équipement et légende utile. Les photos historiques aident à comparer sans devenir une preuve de l’état du jour. Conserver les documents importants tels que PV, analyses et rapports avec leur version. Une photo ne prouve pas l’intérieur d’un conduit, l’autonomie d’un BAES ou l’action d’un capteur non testé.","checks":["Identifier date et local","Relier au contrôle","Vérifier netteté et lisibilité","Distinguer historique et jour"],"evidence":["Photos datées","Documents associés"],"sources":["trames"],"pending":"","review":"contenu de cadrage vérifié"}};
